#!/usr/bin/env python3\n\"\"\"\nأداة لاسترجاع جميع النطاقات الفرعية (subdomains) لاسم نطاق معين\nباستخدام قاعدة بيانات شهادات crt.sh.\n\"\"\"\n\nimport sys\nimport json\nimport requests\n\ndef fetch_subdomains(domain):\n    url = f\"https://crt.sh/?q=%25.{domain}&output=json\"\n    try:\n        resp = requests.get(url, timeout=10, verify=False)\n        resp.raise_for_status()\n        data = resp.json()\n    except Exception:\n        return []\n    subs = set()\n    for entry in data:\n        name = entry.get(\"name_value\")\n        if name:\n            for sub in name.splitlines():\n                subs.add(sub.strip())\n    return sorted(subs)\n\ndef main():\n    if len(sys.argv) > 1:\n        domain = sys.argv[1]\n    else:\n        domain = sys.stdin.read().strip()\n    if not domain:\n        print(json.dumps({\"error\": \"No domain provided\"}))\n        return\n    subdomains = fetch_subdomains(domain)\n    print(json.dumps({\"domain\": domain, \"subdomains\": subdomains}, ensure_ascii=False))\n\nif __name__ == \"__main__\":\n    main()\n